Great! We have a working matrix multiplication kernel. Now let's recap iteration 1 and move to iteration 2.

### Iteration 1 Recap
- Implemented basic matrix multiplication kernel using CUDA
- Each thread computes one element of the output matrix
- Runtime: 3.42 ms
- Correctness: Passed (2/2 trials)

Now let's optimize the kernel for iteration 2 by adding shared memory to reduce global memory accesses.

### Iteration 2: Shared Memory Optimization
We'll implement a tiled matrix multiplication using shared memory to cache blocks of the input matrices.

```python
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# CUDA kernel source with shared memory optimization
cuda_source = """
#include <torch/extension.h>

#define TILE_SIZE 16

__global__ void matmul_kernel(const float* A, const float* B, float* C, int M, int N, int K) {
    // Shared memory for tiles
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    float sum = 0.0f;

    // Loop over tiles
    for (int t = 0; t < (K + TILE_SIZE - 1) / TILE_SIZE; t++) {
        // Load tile of A into shared memory
        int tiled_row = blockIdx.y * TILE_SIZE + threadIdx.y;
        int tiled_col = t * TILE_SIZE + threadIdx.x;
        if (tiled_row < M && tiled_col < K) {
            As[threadIdx.y][threadIdx.x] = A[tiled_row * K + tiled_col];
        } else {
            As[threadIdx.y][threadIdx.x] = 0.0f;
        }

        // Load tile of B into shared memory
        tiled_row = t * TILE_SIZE + threadIdx.y;
        tiled_col = blockIdx.x * TILE_SIZE + threadIdx.x;
        if (tiled_row < K && tiled_col < N) {
            Bs[threadIdx.y][threadIdx.x] = B[tiled_row * N + tiled_col];
        } else {
            Bs[threadIdx.y][threadIdx.x] = 0.0f;
        }

        // Synchronize to ensure tiles are loaded
        __syncthreads();

        // Compute partial dot product
        for (int k = 0; k < TILE_SIZE; k++) {
            sum += As[threadIdx.y][k] * Bs[k][threadIdx.x];
        }

        // Synchronize before loading next tiles
        __syncthreads();
    }

    // Write result to global memory
    if (row < M && col < N) {
        C[row * N + col] = sum;
    }
}

torch::Tensor matmul_forward(torch::Tensor A, torch::Tensor B) {
    int M = A.size(0);
    int K = A.size(1);
    int N = B.size(1);

    // Create output tensor on the same device as input
    auto device_id = A.device().index();
    auto options = torch::TensorOptions().dtype(torch::kFloat32).device(torch::kCUDA, device_id);
    auto C = torch::zeros({M, N}, options);

    // Block and grid dimensions
    dim3 threadsPerBlock(TILE_SIZE, TILE_SIZE);
    dim3 numBlocks((N + TILE_SIZE - 1) / TILE_SIZE, 
                   (M + TILE_SIZE - 1) / TILE_SIZE);

    matmul_kernel<<<numBlocks, threadsPerBlock>>>(A.data_ptr<float>(), 
                                                 B.data_ptr<float>(), 
                                                 C.data_ptr<float>(), 
                                                 M, N, K);

    return C;
}
"""

# C++ wrapper source
cpp_source = """
torch::Tensor matmul_forward(torch::Tensor A, torch::Tensor B);
"""

# Load the CUDA extension
matmul_extension = load_inline(
    name="matmul_extension",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["matmul_forward"],
    extra_cuda_cflags=["-O2"],
    verbose=True
)

# Define the PyTorch module
class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, a, b):
        return matmul_extension.matmul_forward(a, b)
```

