cuda_source = """
#include <torch/extension.h>

#define TILE_SIZE 16
#define UNROLL_FACTOR 4
#define BLOCK_SIZE 2

__global__ void matmul_kernel(const float* A, const float* B, float* C, int M, int N, int K) {
    // Shared memory for tiles
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    int row = blockIdx.y * blockDim.y * BLOCK_SIZE + threadIdx.y;
    int col = blockIdx.x * blockDim.x * BLOCK_SIZE + threadIdx.x;

    // Register block for results
    float c[BLOCK_SIZE][BLOCK_SIZE] = {{0.0f}};

    // Loop over tiles
    for (int t = 0; t < (K + TILE_SIZE - 1) / TILE_SIZE; t++) {
        // Load tile of A into shared memory
        int tiled_row = blockIdx.y * TILE_SIZE + threadIdx.y;
        int tiled_col = t * TILE_SIZE + threadIdx.x;
        if (tiled_row < M && tiled_col < K) {
            As[threadIdx.y][threadIdx.x] = A[tiled_row * K + tiled_col];
        } else {
            As[threadIdx.y][threadIdx.x] = 0.0f;
        }

        // Load tile of B into shared memory
        tiled_row = t * TILE_SIZE + threadIdx.y;
        tiled_col = blockIdx.x * TILE_SIZE + threadIdx.x;
        if (tiled_row < K && tiled_col < N) {
            Bs[threadIdx.y][threadIdx.x] = B[tiled_row * N + tiled_col];
        } else {
            Bs[threadIdx.y][threadIdx.x] = 0.0f;
        }

        // Synchronize to ensure tiles are loaded
        __syncthreads();

        // Compute partial dot product with loop unrolling and register blocking
        for (int k = 0; k < TILE_SIZE; k += UNROLL_FACTOR) {
            #pragma unroll
            for (int bi = 0; bi < BLOCK_SIZE; bi++) {
                #pragma unroll
                for (int bj = 0; bj < BLOCK_SIZE; bj++) {
                    #pragma unroll
                    for (int unroll = 0; unroll < UNROLL_FACTOR; unroll++) {
                        int row_idx = row + bi * blockDim.y;
                        int col_idx = col + bj * blockDim.x;
                        if (row_idx < M && col_idx < N) {
                            c[bi][bj] += As[threadIdx.y + bi * blockDim.y][k + unroll] * 
                                         Bs[k + unroll][threadIdx.x + bj * blockDim.x];
                        }
                    }
                }
            }
        }

        // Synchronize before loading next tiles
        __syncthreads();
    }

    // Write result to global memory
    for (int bi = 0; bi < BLOCK_SIZE; bi++) {
        for (int bj = 0; bj < BLOCK_SIZE; bj++) {
            int row_idx = row + bi * blockDim.y;
            int col_idx = col + bj * blockDim.x;
            if (row_idx < M && col_idx < N) {
                C[row_idx * N + col_idx] = c[bi][bj];
            }
        }
    }
}

